\begin{tikzpicture}[x=12mm,y=12mm,>=stealth]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{functionBlue}{HTML}{268CFF}
\definecolor{functionRed}{HTML}{EF6068}
\definecolor{resultGreen}{HTML}{4F9B63}
\path[use as bounding box] (-2.4,-2.4) rectangle (2.65,2.6);
\draw[black,line width=0.5pt,->] (-2.1,0)--(2.2,0);
\draw[black,line width=0.5pt,->] (0,-2.1)--(0,2.2);
\node[black,anchor=north east,font=\fontsize{10}{12}\selectfont] at (2.2,-0.06) {$x$};
\node[black,anchor=west,font=\fontsize{10}{12}\selectfont] at (0.1,2.12) {$y$};
\draw[functionBlue,line width=0.8pt,<->] (-2,-2)--(2,2);
\draw[functionRed,line width=0.8pt,<->,domain=-1.28:1.28,samples=101] plot (\x,{\x*\x*\x});
\draw[resultGreen,line width=0.8pt,<->,domain=-1.02:1.02,samples=101] plot (\x,{\x+\x*\x*\x});
\node[resultGreen,anchor=east,font=\fontsize{10}{12}\selectfont] at (0.65,1.55) {$x+x^3$};
\fill[black] (-1,-1) circle[radius=0.025];
\fill[black] (0,0) circle[radius=0.025];
\fill[black] (1,1) circle[radius=0.025];
\node[black,anchor=east,font=\fontsize{10}{12}\selectfont] at (-1.12,-0.8) {$(-1,-1)$};
\node[black,anchor=north west,font=\fontsize{10}{12}\selectfont] at (0.08,-0.12) {$(0,0)$};
\node[black,anchor=west,font=\fontsize{10}{12}\selectfont] at (1.12,0.82) {$(1,1)$};
\end{tikzpicture}
